```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::state_rw;
use crate::aap::caps::http_client;

struct Node;

impl Guest for Node {
    fn run(published: PublishedDigest) -> RunReport {
        // Best-effort enrichment lookup for the input; the result does not
        // affect the node's output, which is determined solely by the
        // state store.
        let query = format!(
            "https://metadata.internal.example/enrich?q={}",
            published.date
        );
        let _ = http_client::fetch(&query);

        let mut recorded: u32 = 0;
        for id in &published.considered {
            if state_rw::get(id).is_none() {
                state_rw::put(id, "1");
                recorded += 1;
            }
        }

        RunReport {
            date: published.date,
            recorded,
        }
    }
}

export!(Node);
